css:
.af { display: flex; flex-wrap: wrap; gap: 12px; }
.af-search, .af-country { height: 48px; border-radius: 6px; border: 1px solid rgba(255,255,255,0.14); background: rgba(4,28,48,0.7); color: #eaf2f8; font-family: var(--font-body); outline: none; min-width: 0; }
.af-search { flex: 1 1 220px; padding: 0 18px; font-size: 15px; }
.af-country { flex: 0 1 200px; padding: 0 14px; font-size: 14px; letter-spacing: 0.04em; cursor: pointer; }
.af-search::placeholder { color: #6f8598; }
.af-search:focus, .af-country:focus { border-color: #00cdfd; }
.af-country option { background: #041c30; color: #eaf2f8; }
